create schema icash_work_private;
create table icash_work_private.value_priority_settings(id boolean primary key,enabled boolean);
insert into icash_work_private.value_priority_settings values(true,true);
create table icash_screening_jobs(id uuid primary key,account_id uuid,snapshot jsonb);
create table icash_deal_files(id uuid primary key,account_id uuid,screening_id uuid,terms jsonb);
create table icash_text_threads(id uuid primary key,account_id uuid,deal_id uuid,party text,recipient text,ai_mode text,paused boolean,manual_only boolean,retired_at timestamptz,eligibility_until timestamptz,permission_until timestamptz,timezone text,operational_contact_id uuid);
create table icash_text_messages(id uuid primary key,account_id uuid,thread_id uuid,direction text,state text,provider_id text,event_id text,created_at timestamptz,body text);
create table icash_text_ai_jobs(id uuid primary key,account_id uuid,thread_id uuid,message_id uuid,state text,next_attempt_at timestamptz,outgoing_id uuid);
create table icash_seller_reply_progress(account_id uuid,message_id uuid,state text);
create table icash_voice_jobs(id uuid primary key,account_id uuid,permission_id uuid,operational_contact_id uuid,state text,due_at timestamptz,callback_id uuid,sms_source_message_id uuid,operation_key text,provider_call_sid text);
create table icash_voice_contact_targets(id uuid,account_id uuid,screening_id uuid,party text,phone text,contact_key text,revoked_at timestamptz,permission_until timestamptz,dnc_clear boolean);
create table icash_operational_contacts(id uuid,account_id uuid,channel text,timezone_basis text);
create table icash_property_controls(account_id uuid,property_id text,manual boolean);
create table icash_text_suppressions(phone text);
create table icash_contact_suppressions(contact_key text);
create table fixture_checks(capacity boolean,hours boolean,history boolean);
insert into fixture_checks values(true,true,false);
create sequence capacity_scans;
create sequence history_scans;
create function icash_seller_response_disposition(text) returns text language sql stable as $$select case when $1='STOP' then 'opt_out' end$$;
create function icash_voice_outreach_hours_current(uuid,uuid) returns boolean language sql stable as $$select hours from public.fixture_checks$$;
create function icash_outgoing_voice_capacity_open() returns boolean language plpgsql stable as $$begin perform nextval('public.capacity_scans');return (select capacity from public.fixture_checks);end$$;
create function icash_outreach_active_conversation(uuid,uuid,text,timestamptz) returns boolean language plpgsql stable as $$begin perform nextval('public.history_scans');return (select history from public.fixture_checks);end$$;
create view icash_timezone_names as select name from pg_timezone_names;
